inputs = ['zdkhyy', 'vvkb', 'xcwjag', 'xk', 'eexjfw']
outputs = ['zdkhyy', 'vvkb', 'xvgjag', 'xk', 'eexjfydj']

print("Examining strings carefully:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Example {i}:")
    print(f"  Input:  '{inp}' (len={len(inp)})")
    print(f"  Output: '{outp}' (len={len(outp)})")

    if inp != outp:
        print("  Differences:")
        min_len = min(len(inp), len(outp))
        for j in range(min_len):
            if inp[j] != outp[j]:
                print(f"    Position {j}: '{inp[j]}' -> '{outp[j]}'")

        if len(inp) != len(outp):
            if len(inp) < len(outp):
                print(f"    Appended: '{outp[len(inp):]}'")
            else:
                print(f"    Truncated: '{inp[len(outp):]}'")
    print()

